_CORE_SRC = '# Action format: "[(from_node, to_node, count), ...]"\n# Payout: "revenue_p = sum of node_value[i] over all nodes i that player p owns"\n# Cost: "upkeep_p = UPKEEP * (UNITS_PER_PLAYER - units of p on its own base)"\n# Ownership persists without a garrison; capture requires two consecutive strict\n# majorities. Unlike capacity-sharing games, capture rewards are not concave:\n# the allocator therefore bids for the whole minimum useful capture/defence bundle.\n\nimport time\n\nTIME_BUDGET = 0.25\nN_TURNS = 80\nUPKEEP = 2.0\n\n\ndef payout(values, owned, units_at_base):\n    """Exact one-turn profit, after landing and ownership updates."""\n    return float(sum(v for v, flag in zip(values, owned) if flag)\n                 - UPKEEP * (20 - units_at_base))\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    lengths = {}\n    distance = [[10**6] * n for _ in range(n)]\n    for i in range(n):\n        distance[i][i] = 0\n    for a, b, length in edges:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n        lengths[a, b] = lengths[b, a] = length\n        distance[a][b] = distance[b][a] = length\n    for row in adjacency:\n        row.sort()\n    for k in range(n):\n        for i in range(n):\n            dik = distance[i][k]\n            for j in range(n):\n                candidate = dik + distance[k][j]\n                if candidate < distance[i][j]:\n                    distance[i][j] = candidate\n    hops = [[-1] * n for _ in range(n)]\n    for i in range(n):\n        for j in range(n):\n            if i != j:\n                for neighbor in adjacency[i]:\n                    if lengths[i, neighbor] + distance[neighbor][j] == distance[i][j]:\n                        hops[i][j] = neighbor\n                        break\n    return adjacency, lengths, distance, hops\n\n\ndef legal_action(assignments, units, adjacency, hops):\n    """Route assigned surplus to deficits, then validate against original counts."""\n    aggregated = {}\n    for source, target, count in assignments:\n        if count <= 0 or source == target:\n            continue\n        neighbor = hops[source][target]\n        if neighbor >= 0:\n            key = (source, neighbor)\n            aggregated[key] = aggregated.get(key, 0) + count\n    available = list(units)\n    result = []\n    for (source, target), requested in sorted(aggregated.items()):\n        if not (0 <= source < len(available) and 0 <= target < len(available)):\n            continue\n        if target not in adjacency[source]:\n            continue\n        count = min(int(requested), int(available[source]))\n        if count > 0:\n            result.append((int(source), int(target), int(count)))\n            available[source] -= count\n    return result\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.previous_targets = {}\n        self.bad_reports = 0\n\n    def plan(self, obs, deadline):\n        adjacency, lengths, distance, hops = self.map_data\n        n = len(adjacency)\n        home = int(obs["player_base"])\n        enemy_home = int(obs["opponent_base"])\n        turn = int(obs.get("turn", 0))\n        remaining = max(0, N_TURNS - turn)\n        units = obs["player_units"]\n        enemies = list(obs["opponent_units"])\n        owned = obs["player_owned"]\n        enemy_owned = obs["opponent_owned"]\n        leads = obs["player_lead_turns"]\n        values = obs["node_value"]\n\n        # Future visible landings are counted, rather than sending duplicate forces.\n        for _, destination, count, arrival in obs.get("opponent_transits", []):\n            if arrival <= turn + remaining:\n                enemies[destination] += count\n\n        # Sources include committed travelling units. They reserve target capacity,\n        # but cannot contribute any action until a subsequent observation.\n        sources = []\n        for node, count in enumerate(units):\n            if count:\n                sources.append([node, 0, int(count), True])\n        for _, destination, count, arrival in obs.get("player_transits", []):\n            sources.append([destination, max(0, arrival - turn), int(count), False])\n\n        jobs = []\n        for node in range(n):\n            if node == home or node == enemy_home or values[node] <= 0:\n                continue\n            opposition = enemies[node]\n            if owned[node]:\n                if opposition == 0:\n                    continue\n                required = opposition  # A tie preserves ownership.\n                defence = True\n            else:\n                required = opposition + 1\n                defence = False\n            if required <= 20:\n                jobs.append((node, required, defence))\n\n        assignments = []\n        targets = {}\n        while jobs and time.perf_counter() < deadline:\n            best = None\n            for job_index, (node, required, defence) in enumerate(jobs):\n                choices = []\n                for index, (source, delay, count, movable) in enumerate(sources):\n                    if count <= 0:\n                        continue\n                    travel = delay + distance[source][node]\n                    sticky = self.previous_targets.get(source) == node\n                    ranking = travel - (0.65 if sticky else 0.0)\n                    choices.append((ranking, travel, source, index))\n                choices.sort()\n                selection = []\n                needed = required\n                arrival = 0\n                baseline_cost = 0.0\n                for _, travel, source, index in choices:\n                    take = min(needed, sources[index][2])\n                    if take:\n                        selection.append((index, take, travel))\n                        arrival = max(arrival, travel)\n                        # Returning home is the fallback, not standing away forever.\n                        baseline_cost += UPKEEP * take * min(\n                            remaining,\n                            max(0, sources[index][1] + distance[source][home] - 1)\n                        )\n                        needed -= take\n                    if needed == 0:\n                        break\n                if needed:\n                    continue\n\n                if defence:\n                    capture_delay = arrival\n                elif arrival == 0:\n                    capture_delay = 0 if leads[node] >= 1 else 1\n                else:\n                    capture_delay = arrival\n                earning_turns = max(0, remaining - capture_delay)\n                if earning_turns <= 0:\n                    continue\n\n                # Capturing enemy property gains our revenue AND denies theirs.\n                multiplier = 2.0 if enemy_owned[node] or defence else 1.0\n                if enemies[node] and not owned[node]:\n                    multiplier = 2.0\n                reward = multiplier * values[node] * earning_turns\n\n                if enemies[node]:\n                    # Against a stationary visible opponent the force must remain.\n                    total_cost = UPKEEP * required * remaining\n                else:\n                    # Capture, then recall: account for travel, second lead end,\n                    # and the fact that the final home landing incurs no upkeep.\n                    finish = capture_delay + distance[node][home]\n                    total_cost = UPKEEP * required * min(remaining, max(0, finish))\n                incremental_cost = max(0.0, total_cost - baseline_cost)\n                gain = reward - incremental_cost\n\n                # Some protection against long speculative trips and retargeting.\n                gain -= 0.8 * required * arrival\n                if not owned[node] and units[node] > 0 and leads[node] == 1:\n                    gain += 3.0\n                score = gain / (required ** 0.65)\n                candidate = (score, gain, -arrival, -node)\n                if gain > 1.0 and (best is None or candidate > best[0]):\n                    best = (candidate, job_index, node, selection)\n\n            if best is None:\n                break\n            _, job_index, target, selection = best\n            jobs.pop(job_index)\n            for index, take, _ in selection:\n                source, delay, count, movable = sources[index]\n                sources[index][2] -= take\n                if movable:\n                    assignments.append((source, target, take))\n                    targets[source] = target\n\n        # Spare units are recalled; no standing-away costs are silently ignored.\n        for source, delay, count, movable in sources:\n            if count > 0 and movable and source != home:\n                assignments.append((source, home, count))\n        self.previous_targets = targets\n        return assignments\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.55 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        if self.map_data is None:\n            self.map_data = preprocess_map(n, obs.get("edges", []))\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n        adjacency, lengths, distance, hops = self.map_data\n        units = obs.get("player_units", [0] * n)\n        if self.bad_reports >= 2:\n            home = int(obs["player_base"])\n            assignments = [(node, home, int(count))\n                           for node, count in enumerate(units)\n                           if count > 0 and node != home]\n        else:\n            assignments = self.plan(obs, deadline)\n        return legal_action(assignments, units, adjacency, hops)\n'
