_FALLBACK_SRC = '# Action format: "list[tuple[int, int, int]]", [(from_node, to_node, count), ...].\n# "revenue_p = sum of node_value[i] over all nodes i that player p owns"\n# "upkeep_p = UPKEEP * (UNITS_PER_PLAYER - units of p on its own base)"\n# "profit_p = revenue_p - upkeep_p"\n# Ownership persists without a garrison; capture needs two consecutive strict leads.\n# This conservative fallback uses single scouts, avoids occupied enemy nodes, and\n# budgets the entire outward journey, capture wait, and return before deploying.\n\nTIME_BUDGET = 0.25\nN_TURNS = 80\nUNITS_PER_PLAYER = 20\nUPKEEP = 2.0\n\n\ndef payout(node_value, owned, units_on_base):\n    """The specification\'s per-turn profit, including all transit upkeep."""\n    revenue = sum(value for value, owner in zip(node_value, owned) if owner)\n    upkeep = UPKEEP * (UNITS_PER_PLAYER - units_on_base)\n    return float(revenue - upkeep)\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    distance = [[10**6] * n for _ in range(n)]\n    for u in range(n):\n        distance[u][u] = 0\n    for u, v, length in edges:\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n        distance[u][v] = length\n        distance[v][u] = length\n    for row in adjacency:\n        row.sort()\n    for k in range(n):\n        for u in range(n):\n            for v in range(n):\n                candidate = distance[u][k] + distance[k][v]\n                if candidate < distance[u][v]:\n                    distance[u][v] = candidate\n\n    hop = [[-1] * n for _ in range(n)]\n    for u in range(n):\n        for target in range(n):\n            if u == target:\n                continue\n            for v in adjacency[u]:\n                if distance[u][v] + distance[v][target] == distance[u][target]:\n                    hop[u][target] = v\n                    break\n    return adjacency, distance, hop\n\n\ndef make_plan(obs, distance, hop):\n    n = int(obs["n_nodes"])\n    turn = int(obs.get("turn", 0))\n    remaining = max(0, N_TURNS - turn)\n    home = int(obs["player_base"])\n    enemy_home = int(obs["opponent_base"])\n    units = obs["player_units"]\n    values = obs["node_value"]\n    owned = obs["player_owned"]\n    enemy = list(obs["opponent_units"])\n    leads = obs["player_lead_turns"]\n\n    # Enemy transits are treated as if already defending their destinations.\n    # There is no proportional payout or shared revenue in this game.\n    for source, destination, count, arrival in obs.get("opponent_transits", []):\n        enemy[destination] += count\n\n    reserved = set()\n    proposed = {}\n\n    def choose_target(source, delay=0):\n        candidates = []\n        for target in range(n):\n            if target == home or target == enemy_home:\n                continue\n            if owned[target] or enemy[target] or target in reserved:\n                continue\n            value = int(values[target])\n            if value <= 0:\n                continue\n            travel = distance[source][target]\n            if travel >= 10**6:\n                continue\n\n            # Arrival counts as the first lead. An existing lead at the\n            # current node lets the scout capture at this turn\'s end.\n            if travel == 0 and delay == 0:\n                capture_delay = 0 if leads[target] > 0 else 1\n            else:\n                capture_delay = delay + travel\n            paying_turns = max(0, remaining - capture_delay)\n\n            # An intentionally conservative bound: count even the final\n            # home-arrival turn as costing upkeep, although it is free.\n            away_turns = delay + travel + 2 + distance[target][home]\n            cost = UPKEEP * away_turns\n            revenue = value * paying_turns\n            # Require ample positive lifetime return, not merely break-even.\n            if revenue <= cost * 1.5 + 6.0:\n                continue\n            candidates.append((travel, -value, target))\n        if not candidates:\n            return None\n        return min(candidates)[2]\n\n    # Reserve work for units already travelling before launching anything new.\n    # Each edge destination is known; no persistent mission state is required.\n    for source, destination, count, arrival in obs.get("player_transits", []):\n        delay = max(0, int(arrival) - turn)\n        for _ in range(min(UNITS_PER_PLAYER, int(count))):\n            target = choose_target(destination, delay)\n            if target is not None:\n                reserved.add(target)\n\n    def assign_one(source):\n        target = choose_target(source)\n        if target is not None:\n            reserved.add(target)\n        else:\n            target = home\n        if target != source:\n            destination = hop[source][target]\n            if destination >= 0:\n                key = (source, destination)\n                proposed[key] = proposed.get(key, 0) + 1\n\n    # Away scouts get first choice, so fresh deployments do not steal their\n    # nearby work. Surplus scouts return home rather than paying idle upkeep.\n    for source in range(n):\n        if source != home:\n            for _ in range(min(UNITS_PER_PLAYER, int(units[source]))):\n                assign_one(source)\n    for _ in range(min(UNITS_PER_PLAYER, int(units[home]))):\n        assign_one(home)\n    return proposed\n\n\ndef legal_action(plan, start_units, adjacency):\n    """Validate against start-of-turn availability; arriving units never count."""\n    available = [int(count) for count in start_units]\n    n = len(available)\n    action = []\n    for (source, destination), requested in sorted(plan.items()):\n        source, destination = int(source), int(destination)\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if source == destination or destination not in adjacency[source]:\n            continue\n        count = min(max(0, int(requested)), available[source])\n        if count > 0:\n            action.append((int(source), int(destination), int(count)))\n            available[source] -= count\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = int(player_id)\n        self.map_key = None\n        self.map_data = None\n\n    def act(self, obs):\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0 or not obs.get("player_units"):\n            return []\n\n        edges = obs.get("edges", [])\n        key = (n, tuple(tuple(edge) for edge in edges))\n        if key != self.map_key:\n            self.map_data = preprocess_map(n, edges)\n            self.map_key = key\n        adjacency, distance, hop = self.map_data\n\n        # Feedback never requires changing mission state: there is none.\n        # All moves, including the conservative fallback, use this validator.\n        plan = make_plan(obs, distance, hop)\n        return legal_action(plan, obs["player_units"], adjacency)\n'
_FALLBACK_CLASS = 'Strategy'
_ACT_LIMIT_S = 0.7
_CORE_SHARE = 0.75
_TIME_BUDGET = 0.25
_IMPORT_LIMIT_S = 4.5
_FALLBACK_IMPORT_LIMIT_S = 1.5
_CORE_INIT_LIMIT_S = 2.5
_FALLBACK_INIT_LIMIT_S = 1.5
_MAX_REPLY_CHARS = 900000

_MIN_FALLBACK_S = 0.05
_REPEAT_S = 0.05  # after the first alarm, re-fire every 50 ms until the call returns
_STATE = {"armed": False}
_GUARD_CODES = set()


class _GuardTimeout(BaseException):
    """Raised by the guard's timer. A BaseException: `except Exception` cannot swallow it."""


class _Sink:
    """Swallows output: strategy code must not flood the worker's stderr."""

    encoding = "utf-8"
    errors = "replace"

    def write(self, s):
        return len(s)

    def writelines(self, lines):
        return None

    def flush(self):
        return None

    def isatty(self):
        return False


_SINK = _Sink()


def _noop_print(*args, **kwargs):
    return None


def _on_alarm(signum, frame):
    if _STATE["armed"] and (frame is None or frame.f_code not in _GUARD_CODES):
        raise _GuardTimeout()


def _can_time():
    return (
        hasattr(_signal, "setitimer")
        and hasattr(_signal, "SIGALRM")
        and _threading.current_thread() is _threading.main_thread()
    )


def _plain(value):
    """(True, plain copy) if value is a literal within the reply limit, else (False, None)."""
    try:
        text = repr(value)
        if len(text) > _MAX_REPLY_CHARS:
            return False, None
        if not text.isascii() and len(text.encode("utf-8", "replace")) > _MAX_REPLY_CHARS:
            return False, None  # arena's reply limit counts bytes
        copy = _ast.literal_eval(text)
        if not bool(copy == value):  # NaN, or a type whose repr is not its value
            return False, None
        return True, copy
    except Exception:
        return False, None


def _call(fn, args, limit, check):
    """fn(*args) under a hard timer: (status, value, error, secs). Never raises.

    status: 'ok', 'timeout', 'exception' or 'bad' (check=True and not a plain literal).
    """
    status = "exception"
    value = None
    error = None
    timed = False
    prev_handler = None
    prev_timer = (0.0, 0.0)
    out, err, inp = _sys.stdout, _sys.stderr, _sys.stdin
    t0 = _time.perf_counter()
    try:
        if limit > 0 and _can_time():
            prev_handler = _signal.signal(_signal.SIGALRM, _on_alarm)
            prev_timer = _signal.setitimer(_signal.ITIMER_REAL, limit, _REPEAT_S)
            timed = True
        _sys.stdout = _sys.stderr = _SINK
        _sys.stdin = None  # arena's protocol pipe: untrusted code must not read it
        _STATE["armed"] = timed
        try:
            result = fn(*args)
            if check:
                ok, result = _plain(result)
                status = "ok" if ok else "bad"
            else:
                status = "ok"
            value = result
        except _GuardTimeout as e:
            status = "timeout"
            error = e
        except BaseException as e:
            status = "exception"
            error = e
    except BaseException as e:
        if status == "exception" and error is None:
            error = e
    finally:
        _STATE["armed"] = False
        if timed:
            try:
                _signal.setitimer(_signal.ITIMER_REAL, 0.0)
                _signal.signal(
                    _signal.SIGALRM, prev_handler if prev_handler is not None else _signal.SIG_DFL
                )
                if prev_timer[0] > 0:
                    spent = _time.perf_counter() - t0
                    _signal.setitimer(
                        _signal.ITIMER_REAL, max(prev_timer[0] - spent, 1e-4), prev_timer[1]
                    )
            except BaseException:
                pass
        _sys.stdout, _sys.stderr, _sys.stdin = out, err, inp
    if isinstance(error, _GuardTimeout):
        status = "timeout"
    return status, value, error, _time.perf_counter() - t0


_GUARD_CODES.add(_call.__code__)  # exempt already while the embedded sources load


def _act_of(strategy, obs):
    """strategy.act(obs): inside the timed call, so a missing or broken `act` is caught too."""
    return strategy.act(obs)


def _describe(status, error, secs, limit):
    if status == "timeout":
        where = ""
        try:
            if error is not None:
                frames = _traceback.extract_tb(error.__traceback__)
                frames = [f for f in frames if f.name not in ("_on_alarm", "_call")][-3:]
                where = "\ninterrupted at:\n" + "".join(_traceback.format_list(frames))
        except BaseException:
            where = ""
        return "timeout: no result within %.2f s (limit %.2f s)%s" % (secs, limit, where[-1500:])
    if status == "bad":
        return "bad output: not a plain Python literal within the reply limit"
    try:
        return "".join(_traceback.format_exception(error))[-4000:]
    except BaseException:
        return "exception (traceback unavailable)"


def _load(src, cls_name, label):
    n = 0
    while "_hz_%s_%d" % (label, n) in _sys.modules:
        n += 1
    name = "_hz_%s_%d" % (label, n)
    filename = "<%s>" % name
    _linecache.cache[filename] = (len(src), None, src.splitlines(True), filename)
    module = _types.ModuleType(name)
    module.__file__ = filename
    module.TIME_BUDGET = _TIME_BUDGET
    module.print = _noop_print
    _sys.modules[name] = module
    try:
        exec(compile(src, filename, "exec"), module.__dict__)
        module.TIME_BUDGET = _TIME_BUDGET
        module.print = _noop_print
        return getattr(module, cls_name)
    except BaseException:
        _sys.modules.pop(name, None)
        raise


_LOAD_ERRORS = {}


def _load_all():
    t0 = _time.perf_counter()
    loaded = {"core": None, "fallback": None}
    parts = (
        ("fallback", _FALLBACK_SRC, _FALLBACK_CLASS, _FALLBACK_IMPORT_LIMIT_S),
        ("core", _CORE_SRC, _CORE_CLASS, None),
    )
    for label, src, cls_name, limit in parts:
        if src is None:
            continue
        left = _IMPORT_LIMIT_S - (_time.perf_counter() - t0)
        limit = min(limit, left) if limit is not None else left
        limit = max(limit, 0.5)
        status, value, error, secs = _call(_load, (src, cls_name, label), limit, False)
        if status == "ok":
            loaded[label] = value
        else:
            _LOAD_ERRORS[label] = _describe(status, error, secs, limit)
    return loaded["core"], loaded["fallback"]


try:
    _CORE_CLS, _FALLBACK_CLS = _load_all()
except BaseException:
    _CORE_CLS, _FALLBACK_CLS = None, None


class _HzGuard:
    def __init__(self, player_id):
        self.player_id = player_id
        self._core = None
        self._fallback = None
        self._stats = {
            "turns": 0,
            "core_ok": 0,
            "core_exceptions": 0,
            "core_timeouts": 0,
            "core_bad_output": 0,
            "fallback_used": 0,
            "fallback_failures": 0,
            "none_used": 0,
            "max_core_s": 0.0,
            "first_core_traceback": _LOAD_ERRORS.get("core"),
            "core_loaded": _CORE_CLS is not None,
            "fallback_loaded": _FALLBACK_CLS is not None,
            "core_init_error": None,
            "fallback_init_error": None,
            "fallback_load_error": _LOAD_ERRORS.get("fallback"),
            "first_fallback_error": None,
        }
        try:
            if _CORE_CLS is not None:
                lim = _CORE_INIT_LIMIT_S
                status, value, error, secs = _call(_CORE_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._core = value
                else:
                    msg = _describe(status, error, secs, lim)
                    self._stats["core_init_error"] = msg
                    if self._stats["first_core_traceback"] is None:
                        self._stats["first_core_traceback"] = msg
            if _FALLBACK_CLS is not None:
                lim = _FALLBACK_INIT_LIMIT_S
                status, value, error, secs = _call(_FALLBACK_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._fallback = value
                else:
                    self._stats["fallback_init_error"] = _describe(status, error, secs, lim)
        except BaseException:
            pass

    def act(self, obs):
        try:
            return self._act(obs)
        except BaseException:
            return None

    def _act(self, obs):
        t0 = _time.perf_counter()
        st = self._stats
        st["turns"] += 1
        core, fallback = self._core, self._fallback
        saved = None
        if core is not None:
            if fallback is not None:
                try:
                    saved = repr(obs)  # the core may mutate obs; the fallback gets a fresh copy
                except Exception:
                    saved = None
            limit = _ACT_LIMIT_S * _CORE_SHARE
            status, value, error, secs = _call(_act_of, (core, obs), limit, True)
            if secs > st["max_core_s"]:
                st["max_core_s"] = secs
            if status == "ok":
                st["core_ok"] += 1
                return value
            if status == "timeout":
                st["core_timeouts"] += 1
            elif status == "bad":
                st["core_bad_output"] += 1
            else:
                st["core_exceptions"] += 1
            if st["first_core_traceback"] is None:
                st["first_core_traceback"] = _describe(status, error, secs, limit)
            error = None
        if fallback is not None:
            fobs = obs
            if saved is not None:
                try:
                    fobs = _ast.literal_eval(saved)
                except Exception:
                    fobs = obs
            left = _ACT_LIMIT_S - (_time.perf_counter() - t0)
            if left >= _MIN_FALLBACK_S:
                status, value, error, secs = _call(_act_of, (fallback, fobs), left, True)
                if status == "ok":
                    st["fallback_used"] += 1
                    return value
                st["fallback_failures"] += 1
                if st["first_fallback_error"] is None:
                    st["first_fallback_error"] = _describe(status, error, secs, left)
        st["none_used"] += 1
        return None

    def guard_stats(self):
        """Counters of this instance: how often the core answered, failed, fell back."""
        try:
            return dict(self._stats)
        except BaseException:
            return {}


for _fn in (_call, _HzGuard.__init__, _HzGuard.act, _HzGuard._act, _HzGuard.guard_stats):
    _GUARD_CODES.add(_fn.__code__)
del _fn


class Strategy(_HzGuard):
    """Guarded strategy: never raises, never exceeds its time limit."""
